changeSet.sql:
ALTER TABLE feedback DROP CONSTRAINT chk_feedback_suppression_reason;
ALTER TABLE feedback ADD CONSTRAINT chk_feedback_suppression_reason
    CHECK (suppression_reason IS NULL OR suppression_reason IN ('VOLUME_CAPPED', 'COMPOSER_DEDUPED', 'COMPOSER_WITHHELD', 'REACTED_DISPUTED', 'REACTED_NOT_APPLICABLE', 'CONVERSATION_EXPIRED', 'ARTIFACT_GONE', 'ARTIFACT_CLOSED', 'ISSUE_SNAPSHOT_CHANGED', 'ARTIFACT_MERGED', 'ARTIFACT_DRAFT', 'RECIPIENT_OPTED_OUT', 'EMPTY_AFTER_SANITIZE', 'INSTANCE_SILENCED', 'PRACTICE_REQUIRES_APPROVAL', 'BACKFILL_QUIET', 'WORKSPACE_DISABLED', 'APPROVAL_STALE', 'APPROVAL_NO_LONGER_ELIGIBLE', 'WORKSPACE_DELIVERY_PAUSED', 'STALE_ROLLOUT_REVISION', 'OUTSIDE_CURRENT_COVERAGE', 'OBSERVATION_INVALIDATED', 'REPEATS_DELIVERED_NOTE', 'REVIEWED_REVISION_CHANGED'));
ALTER TABLE feedback_placement DROP CONSTRAINT chk_feedback_placement_placement;
ALTER TABLE feedback_placement ADD CONSTRAINT chk_feedback_placement_placement
    CHECK (placement_type IN ('SUMMARY', 'INLINE', 'CONVERSATION_TURN', 'LOCATION_COMMENT'));
